create table if not exists classroom_attendance (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, class_id uuid, learner_id uuid, joined_at timestamptz, left_at timestamptz, total_present_seconds int not null default 0, total_disconnected_seconds int not null default 0, status text not null default 'tracking' check (status in ('tracking','present','partial','absent')), finalized_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now()); alter table classroom_attendance enable row level security; create index if not exists idx_classroom_attendance_room on classroom_attendance(room_id); create index if not exists idx_classroom_attendance_learner on classroom_attendance(learner_id);
